CREATE TABLE materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, material_code text NOT NULL, material_name text NOT NULL, category text, unit text NOT NULL DEFAULT 'pcs', opening_stock numeric(12,3) NOT NULL DEFAULT 0, reorder_level numeric(12,3) NOT NULL DEFAULT 0, avg_unit_cost numeric(12,4) NOT NULL DEFAULT 0, preferred_vendor text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by, material_code))